PREVIOUS_AVERAGE_UP = """
CREATE FUNCTION carriedresult_previous_average_fits() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.kind <> 'previous_semester_average' THEN
    RETURN NEW;
  END IF;
  PERFORM 1 FROM schools_subject s
    WHERE s.school_id = NEW.school_id AND s.id = NEW.subject_id AND s.assessment = 'scored'
    FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'a previous semester average is for a scored subject' USING ERRCODE = '23514',
      CONSTRAINT = 'carriedresult_previous_average_fits';
  END IF;
  PERFORM 1 FROM schools_term t
    JOIN schools_term earlier ON earlier.school_id = t.school_id
     AND earlier.school_year_id = t.school_year_id AND earlier.id <> t.id
     AND earlier.ends_on < t.starts_on
    WHERE t.school_id = NEW.school_id AND t.id = NEW.term_id
    FOR SHARE OF t, earlier;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'a previous semester average needs an earlier term in the school year'
      USING ERRCODE = '23514', CONSTRAINT = 'carriedresult_previous_average_fits';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER carriedresult_previous_average_fits BEFORE INSERT ON grades_carriedresult
  FOR EACH ROW EXECUTE FUNCTION carriedresult_previous_average_fits();
"""
